class Solution {
    int distance(const vector<int>& a, const vector<int>& b) {
        return abs(a[0] - b[0]) + abs(a[1] - b[1]);
    }

public:
    int minDistance(int height, int width, vector<int>& tree,
                    vector<int>& squirrel, vector<vector<int>>& nuts) {
        int total = 0, bestDelta = INT_MAX;
        for (const auto& nut : nuts) {
            int toTree = distance(nut, tree);
            total += 2 * toTree;
            bestDelta = min(bestDelta, distance(squirrel, nut) - toTree);
        }
        return total + bestDelta;
    }
};
